if (kind === 'story') return StoryClientGenerated.named(this.api, id)
if (kind === 'scenario') return ScenarioClientGenerated.named(this.api, id)
return EpicClientGenerated.named(this.api, id)

const without = (ids: string[], id: string) => ids.filter(each => each !== id).join('\n')
const moved = after.find((id, index) => id !== before[index] && without(before, id) === without(after, id))
if (!moved) return this
const next = after[after.indexOf(moved) + 1]
if (next) return this.took(this.nodeOf(moved, kind).moveBefore(next))
let answered: this | null = this
for (const passed of before.slice(before.indexOf(moved) + 1)) answered = await this.took(this.nodeOf(passed, kind).moveBefore(moved))
return answered

return steps.flatMap(step => [step, ...step.ands]).map((step, index) => {
  const keyword = step.keyword.toLowerCase() as StepKeyword
  return { id: step.node, parent_id: parent, step_type: KEYWORDS.includes(keyword) ? keyword : 'given', text: step.text, sequential_order: index + 1 }
})

const stories = this.epics.flatMap(epic => epic.sub_epics.flatMap(sub => sub.stories))
const scenarios = stories.flatMap(story => story.scenarios)
return [...this.epics, ...this.epics.flatMap(epic => epic.sub_epics), ...stories, ...scenarios]

own = self._rendered(self.own_format)
if self._read_again(own).strip() != own.strip():
    raise StoryMapEditRefused(self._story_map, "save", f"{self.file} would not keep the edit: {self.own_format} does not read it back")
written = [self._write(self.own_format, self._path)]
for chosen in self.fidelity.session_output.chosen_formats:
    if Format(chosen) != self.own_format:
        written.append(self._write(Format(chosen), self._path.with_suffix(Format(chosen).extension)))
self._session.graph.refresh([str(path) for path in written])
self._read_back = own
return written

if self._read_back.strip() == self._path.read_text(encoding="utf-8").strip():
    return ""
return f"saving would rewrite {self.file}, a {self.fidelity.name} file, beyond the edit: its text is not laid out as {self.own_format} writes a story map"
